[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param([Parameter(Mandatory=$true)][string]$GamePath,[string]$BackupPath)
$ErrorActionPreference='Stop';if(Get-Process -Name 'Cyberpunk2077' -ErrorAction SilentlyContinue){throw 'Close Cyberpunk 2077 before rollback.'}
$Game=[IO.Path]::GetFullPath($GamePath).TrimEnd('\');$ProjectRoot=Split-Path -Parent $PSScriptRoot;$DefaultBackupRoot=Join-Path $ProjectRoot '.deployment_backups';$Allowed=@((Join-Path $Game 'bin\x64\plugins\cyber_engine_tweaks\mods\siena_npc_controller'),(Join-Path $Game 'r6\tweaks\siena_npc'),(Join-Path $Game 'archive\pc\mod\siena_npc.archive'),(Join-Path $Game 'archive\pc\mod\siena_npc.archive.xl'))
if(-not$BackupPath){if(Test-Path -LiteralPath $DefaultBackupRoot){$BackupPath=Get-ChildItem -LiteralPath $DefaultBackupRoot -Directory|Sort-Object Name -Descending|Select-Object -First 1 -ExpandProperty FullName}}
if($BackupPath){$Backup=[IO.Path]::GetFullPath($BackupPath).TrimEnd('\');$ManifestPath=Join-Path $Backup 'deployment.json';if(-not(Test-Path -LiteralPath $ManifestPath -PathType Leaf)){throw 'Rollback manifest missing.'};$Manifest=Get-Content -LiteralPath $ManifestPath -Raw|ConvertFrom-Json;if(([IO.Path]::GetFullPath($Manifest.game_root).TrimEnd('\'))-ne$Game){throw 'Rollback manifest belongs to another game root.'};$Entries=$Manifest.entries}else{$Entries=$Allowed|ForEach-Object{[pscustomobject]@{target=$_;backup=$null;existed=$false;directory=(Test-Path -LiteralPath $_ -PathType Container)}}}
foreach($Entry in $Entries){$Target=[IO.Path]::GetFullPath([string]$Entry.target);if($Target-notin$Allowed){throw "Rollback manifest contains an unowned target: $Target"};if($PSCmdlet.ShouldProcess($Target,'Restore/remove Siena-owned deployment path')){if(Test-Path -LiteralPath $Target){Remove-Item -LiteralPath $Target -Recurse -Force};if($Entry.existed){if(-not(Test-Path -LiteralPath $Entry.backup)){throw "Backup payload missing: $($Entry.backup)"};New-Item -ItemType Directory -Path (Split-Path -Parent $Target) -Force|Out-Null;Copy-Item -LiteralPath $Entry.backup -Destination $Target -Recurse -Force}}}
Write-Host $(if($BackupPath){"Restored prior Siena state from: $BackupPath"}else{'Removed only Siena-owned active paths; no backup was available.'})
